    modifier isSameFamily(uint64 minerIdPayee, uint64 minerIdPayer) {
        require(_minerBindsMap[minerIdPayer] != address(0), "Not bind");
        require(_minerBindsMap[minerIdPayer] == _minerBindsMap[minerIdPayee], "Not same family");
        _;
